			name:       "opencode-document",
			transcript: `{"info":{"id":"ses_x"},"messages":[{"info":{"role":"user"},"parts":[{"type":"text","text":"Remove the header bottom border"}]},{"info":{"role":"assistant"},"parts":[{"type":"text","text":"Removed both borders."}]},{"info":{"role":"user"},"parts":[{"type":"text","text":"you broke the layout"}]}]}`,
			want:       reinforcementCorrected,
