	if err := writeBrainManifestAndReadme(outputDir, *manifest); err != nil {
		return nil, err
	}
	return source, nil
}

func buildBrainHistoryIndex(outputDir string, now time.Time, progress historyIndexProgress) (historyIndex, *historySourceManifest, error) {
	sessionsRoot := filepath.Join(outputDir, exportSessionsDirectory)
	index := historyIndex{GeneratedAt: now}
	if _, err := os.Stat(sessionsRoot); err != nil {
		if os.IsNotExist(err) {
			return index, nil, errors.New("session history missing; run `entire brain refresh sessions` first")
		}
		return index, nil, err
	}
	files, err := collectHistorySessionFiles(sessionsRoot, &index.Warnings)
	if err != nil {
		return index, nil, err
	}

	prevCache := loadHistoryScanCache(outputDir)
	newCache := historyScanCache{Version: historyScanCacheVersion, Files: make(map[string]historyScanCacheEntry, len(files))}
	manifest, _ := loadBrainManifest(outputDir)
	branchByPath := historyBranchByTranscriptPath(manifest)

	total := len(files)
	if progress != nil {
		progress(0, total)
	}
	seenDecisions := map[string]struct{}{}
	for i, file := range files {
		rel, relErr := filepath.Rel(outputDir, file.Path)
		if relErr != nil {
			rel = file.Path
		}
		rel = filepath.ToSlash(rel)

		var records []historyRecord
		if cached, ok := prevCache.Files[rel]; ok && cached.Size == file.Size && cached.ModUnixNano == file.ModUnixNano {
			records = cached.Records
		} else {
			scanned, scanErr := scanHistoryFile(outputDir, file.Path)
			if scanErr != nil {
				index.Warnings = append(index.Warnings, scanErr.Error())
				if progress != nil {
					progress(i+1, total)
				}
				continue
			}
			records = scanned
		}
		records = annotateHistoryRecordBranches(records, rel, branchByPath)
		// Only files that scanned cleanly (or were reused) are cached; a file
		// that errored is left out so the next refresh retries it.
		newCache.Files[rel] = historyScanCacheEntry{Size: file.Size, ModUnixNano: file.ModUnixNano, Records: records}

		for _, record := range records {
			if record.Kind == "decision" {
				dedupeKey := normalizeHistorySearchText(record.Summary)
				if _, ok := seenDecisions[dedupeKey]; ok {
					continue
				}
				seenDecisions[dedupeKey] = struct{}{}
			}
			index.Records = append(index.Records, record)
		}
		if progress != nil {
			progress(i+1, total)
		}
	}
	saveHistoryScanCache(outputDir, newCache)
	sort.Slice(index.Records, func(i, j int) bool {
		if index.Records[i].Kind != index.Records[j].Kind {
			return index.Records[i].Kind < index.Records[j].Kind
		}
		if index.Records[i].Path != index.Records[j].Path {
			return index.Records[i].Path < index.Records[j].Path
		}
		return index.Records[i].Line < index.Records[j].Line
	})
	source := &historySourceManifest{
		GeneratedAt:         now,
		IndexPath:           historyIndexPath,
		SessionsFingerprint: brainSessionsFingerprint(outputDir),
		Records:             len(index.Records),
		Warnings:            append([]string(nil), index.Warnings...),
	}
	for _, record := range index.Records {
		switch record.Kind {
		case "decision":
			source.Decisions++
		case "learning":
			source.Learnings++
		case "validation":
			source.Validations++
		case "tool_call":
			source.ToolCalls++
		case "code_fact":
			source.CodeFacts++
		}
	}
	return index, source, nil
}

func historyBranchByTranscriptPath(manifest *exportManifest) map[string]string {
	out := map[string]string{}
	if manifest == nil || manifest.Sources == nil || manifest.Sources.Sessions == nil {
		return out
	}
	defaultBranch := strings.TrimSpace(manifest.Sources.Sessions.DefaultBranch)
	if defaultBranch == "" {
		defaultBranch = strings.TrimSpace(manifest.DefaultBranch)
	}
	if defaultBranch == "" {
		defaultBranch = distillDefaultBranch
	}
	for _, session := range manifest.Sources.Sessions.Sessions {
		rel := filepath.ToSlash(strings.TrimSpace(session.TranscriptPath))
		if rel == "" {
			continue

// brainBriefFileMatchStop holds the filename-matching-specific stopwords layered
// on top of the shared genericQueryStopwords (see history.go) — mostly extra
// task verbs ("add"/"update"/"change"/"ensure") and short fillers. Domain nouns
// like "regression"/"preserve" are deliberately ABSENT (unlike
// historyQueryStopword) because they are strong filename-match terms here, e.g.
// a "fix the regression detector" task should still match regression.go.
var brainBriefFileMatchStop = map[string]bool{
	"these": true, "those": true, "after": true, "their": true, "your": true,
	"also": true, "was": true, "will": true, "had": true, "using": true,
	"used": true, "add": true, "update": true, "change": true, "ensure": true,
	"running": true, "set": true, "get": true,
	// Common 3-char fillers (matched now that the floor is 3, so that strong
	// 3-char identifiers like "api"/"cli" are kept while filler is dropped).
	"all": true, "any": true, "one": true, "two": true, "old": true,
	"per": true, "off": true, "out": true, "now": true, "yet": true,
	"way": true, "see": true, "let": true, "may": true, "you": true,
}

// brainBriefFileMatchTermStop reports whether a task token is filler for
// filename matching: a generic English/task stopword (shared, single source of
// truth) or a filename-matching-specific filler.
func brainBriefFileMatchTermStop(word string) bool {
	return genericQueryStopwords[word] || brainBriefFileMatchStop[word]
}

// Floor is 3 (not 4) so high-signal short identifiers like "api"/"cli" are not
// skipped; common 3-char filler words are removed by brainBriefFileMatchTermStop.
// The class is Unicode-aware (\p{L}\p{N}, not just [a-z0-9]) so a non-Latin or
// accented task ("café", "認証") still yields terms — matching the history-search
// tokenizer (normalizeHistorySearchText), which is already Unicode-aware. Input
// is lowercased first; foreign tokens simply aren't in the (English) stopword
// maps, so they pass through as content terms rather than being silently dropped.
var brainBriefTaskWordPattern = regexp.MustCompile(`[\p{L}\p{N}]{3,}`)

// brainBriefFileMatchTerms extracts the significant lowercase tokens from a task
// description used to bias likely_edit_files toward files named after the task.
func brainBriefFileMatchTerms(task string) []string {
	seen := map[string]bool{}
	out := []string{}
	for _, word := range brainBriefTaskWordPattern.FindAllString(strings.ToLower(task), -1) {
		if brainBriefFileMatchTermStop(word) || seen[word] {
			continue
		}
		seen[word] = true
		out = append(out, word)

