		}
		var ep episodeRecord
		if err := json.Unmarshal([]byte(line), &ep); err != nil {
			return nil, fmt.Errorf("parse episode line: %w", err)
		}
		episodes = append(episodes, ep)
	}
	return episodes, nil
}

